import {TODAY,uid,norm,amount,days,initialWorkspace,newRequest,validateRequest,comparison,optimize,fixBaseline,finalize,historyFor,recommendations,reconcile,requestDocument,validateWorkspace,materialMargin,actualSummary} from './rfq-domain.mjs';
import * as store from './rfq-store.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),yen=n=>n===null||n===undefined?'未算出':'¥'+n.toLocaleString('ja-JP',{maximumFractionDigits:2}),num=n=>Number(n).toLocaleString('ja-JP',{maximumFractionDigits:3});
let renderedPageKey='';
let mode=localStorage.getItem('gaina-rfq-mode')||'sample',w=await store.load(['live','sample'].includes(mode)?mode:'sample'),requestId=w.requests[0]?.id,stage='compare',substep=0,selectedItem='',insightTab='suggestions',afterTab='orders',toastTimer,busy=false,previewUrl='',importTable=null;
const req=()=>w.requests.find(r=>r.id===requestId),project=r=>w.projects.find(p=>p.id===r?.projectId),vendor=id=>w.vendors.find(v=>v.id===id)?.name||'未登録',today=()=>w.mode==='sample'?TODAY:new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Tokyo'}).format(new Date()),currentItem=()=>req()?.items.find(i=>i.id===selectedItem)||req()?.items[0];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}
async function commit(label='変更を保存'){w.audit.push({id:uid(),action:label,requestId:req()?.id||null,at:new Date().toISOString(),actor:'端末利用者',companyId:w.companyId});if(w.audit.length>500)w.audit=w.audit.slice(-500);try{w=await store.save(w);$('#saveState').textContent='✓ 保存済み · '+new Date().toLocaleTimeString('ja-JP',{timeZone:'Asia/Tokyo',hour:'2-digit',minute:'2-digit'});return true}catch(e){$('#saveState').textContent='保存できません：'+e.message;throw e}}
function modal(title,body){$('#modalEyebrow').textContent=title;$('#modalBody').innerHTML=body;$('#modal').showModal()}
function closeModal(){$('#modal').close();document.body.classList.remove('print-doc')}
const button=(action,label,cls='',extra='')=>`<button data-action="${action}" class="${cls}" ${extra}>${label}</button>`;
const badge=(label,kind='')=>`<span class="badge ${kind}">${esc(label)}</span>`;
const field=(label,name,value,type='text',extra='')=>`<label>${label}<input data-field="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function table(heads,rows,cls=''){return `<div class="table-wrap"><table class="${cls}"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function actions(back,next,caption=''){return `<div class="screen-actions"><div>${back?button(back.action,back.label):`<p>${caption}</p>`}</div><div class="right">${next||''}</div></div>`}
function render(){const r=req();const pageKey=stage+':'+requestId+':'+substep;if(pageKey!==renderedPageKey){window.scrollTo({top:0,behavior:'instant'});renderedPageKey=pageKey;}if(r&&!r.items.some(i=>i.id===selectedItem))selectedItem=r.items[0]?.id||'';$('#dataMode').value=w.mode;$('#modeBadge').textContent=w.mode==='sample'?'サンプル':'自分のデータ';$('#projectName').textContent=project(r)?.name||'仕入・相見積';$('#requestNumber').textContent=r?.number||'案件一覧';$('#requestSelect').innerHTML=w.requests.map(r=>`<option value="${r.id}" ${r.id===requestId?'selected':''}>${esc(r.number+' / '+project(r)?.name)}</option>`).join('');$('#pageSubtitle').textContent=({request:'必要な情報を、ひとつずつ確認して依頼へ。',compare:'品目ごとの選択と、送料込みの総額を確認。',adopt:'採用条件を確定し、仕入先別の発注明細を作成。',history:'数量・時期・仕様が比較できる履歴を確認。',market:'適用日と対象品を分けて、価格改定を管理。',settings:'判定条件・保存データと、接続の対応範囲。',projects:'現場ごとの依頼と、確定した原価を一覧で。',requests:'資料の取込から、発注・購入後の照合まで。'})[stage];$('#flow').hidden=!r||!['request','compare','adopt'].includes(stage);$$('[data-stage]').forEach(b=>{b.classList.toggle('active',b.dataset.stage===stage);b.classList.toggle('done',stage==='adopt'&&b.dataset.stage!=='adopt'||stage==='compare'&&b.dataset.stage==='request')});$('#saveDraft').hidden=!r;$('#screen').innerHTML=!r&&['request','compare','adopt'].includes(stage)?renderProjects():({request:renderRequest,compare:renderCompare,adopt:renderAdopt,history:renderHistoryPage,market:renderMarket,settings:renderSettings,projects:renderProjects,requests:renderProjects}[stage]||renderProjects)();if(stage==='request')updatePreview();if(location.hash!=='#'+stage)history.replaceState(null,'','#'+stage);}
function renderProjects(){return `<div class="inline spread" style="margin-bottom:20px"><h2>案件・依頼一覧</h2>${button('new','＋ 新しい依頼','primary')}</div>${!w.requests.length?'<div class="card empty"><h3>最初の現場を登録しましょう</h3><p>図面・明細がなくても、手入力で依頼を作れます。</p></div>':`<div class="project-cards">${w.requests.map(r=>`<article class="card project-card"><div class="inline spread"><span class="eyebrow">${esc(r.number)} / 第${r.version}版</span>${badge(r.status,r.status==='下書き'?'neutral':'')}</div><h3>${esc(project(r)?.name)}</h3><p>${r.items.length}明細 · ${r.vendorIds.length}社へ依頼<br>希望納期 ${esc(r.conditions.needDate)}</p><div class="inline">${button('open-request','依頼を開く','','data-id="'+r.id+'"')}${r.adoptions.length?badge('予定原価 '+yen(r.adoptions.at(-1).plannedCost),'blue'):''}${button('project-ledger','現場別の採用明細','text',`data-id="${r.projectId}"`)}</div></article>`).join('')}</div>`}`}
function docs(){const r=req();return r.sourceIds.map(id=>w.documents?.find(d=>d.id===id)||({id,name:id==='sample-drawing'?'照明設備図.pdf':'金抜き明細.xlsx',kind:id==='sample-drawing'?'pdf':'xlsx',status:'確認済',sample:true}));}
function renderRequest(){const r=req(),steps=['資料を取り込む','明細を確認','依頼条件','プレビュー'];return `<nav class="substeps">${steps.map((s,i)=>button('request-step',`<span>${i+1}</span> ${s}`,i===substep?'active':i<substep?'complete':'',`data-step="${i}"`)).join('')}</nav>${[requestSources,requestItems,requestConditions,requestPreview][substep]()}`}
function requestSources(){const files=docs();return `<div class="panel-grid"><article class="card"><div class="card-head"><h2>01　資料を取り込む</h2>${badge('PDF・Excel・画像','neutral')}</div><div class="card-body"><div class="dropzone" id="dropzone"><span class="drop-icon"><svg width="34" height="34" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M16 22V5m-6 6 6-6 6 6M5 21v7h22v-7"/></svg></span><h3>図面・金抜き明細を追加</h3><p>紙の図面は撮影、またはスキャンしたPDFで。</p><div class="inline"><label class="file-button">ファイルを選択<input id="sourceFiles" type="file" multiple accept=".pdf,.xlsx,.csv,.png,.jpg,.jpeg"></label><label class="file-button">カメラで撮影<input id="cameraFile" type="file" accept="image/*" capture="environment"></label></div></div><div class="file-list">${files.map(d=>`<div class="file-row"><span class="file-type">${esc(d.kind.toUpperCase())}</span><div class="file-info"><strong>${esc(d.name)}</strong><small>${d.sample?'操作用サンプル':d.hash?.slice(0,12)+'… / 原本保存済み'}</small></div>${badge(d.status,d.status==='要確認'?'warn':'')}${button('preview-source','開く','','data-id="'+d.id+'"')}${!d.sample?button('remove-source','削除','text','data-id="'+d.id+'"'):''}</div>`).join('')}</div><p class="hint">Excel・CSVは列を対応付けて実際の明細を取り込めます。PDF・画像は原本を表示し、明細を手入力してください。自動OCR・図面の数量計測は未接続です。</p></div></article><article class="card"><div class="card-head"><h2>原本プレビュー</h2>${badge('照合しながら確認','blue')}</div><div class="card-body"><div class="drawing"><div class="preview-toolbar"><select id="previewSource" aria-label="プレビューする原本">${files.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select></div><div id="sourcePreview">${sampleDrawing()}</div><p class="preview-note">価格は回答見積から取得。金抜き明細からは推測しません。</p></div></div></article></div>${actions(null,button('request-next','明細を確認する →','primary'),files.length+'資料 / 端末内に原本保存')}`}
function sampleDrawing(){return `<svg viewBox="0 0 580 380" role="img" aria-label="設備配置のサンプル図"><rect x="5" y="5" width="570" height="370" fill="white" stroke="#c9d3e1"/><text x="25" y="35" fill="#74849b" font-size="12">E-01 設備配置図 / SAMPLE</text><path d="M45 65H535V305H45ZM285 65V305M45 185H535" fill="none" stroke="#8e9eae" stroke-width="3"/>${[115,220,350,455].map(x=>`<rect x="${x-30}" y="108" width="60" height="12" fill="#e7edf6" stroke="#7c94b1"/><rect x="${x-30}" y="235" width="60" height="12" fill="#e7edf6" stroke="#7c94b1"/>`).join('')}<path d="M70 270V115H470V240" fill="none" stroke="#5488be" stroke-width="2" stroke-dasharray="6 5"/><rect x="53" y="256" width="35" height="35" fill="#edf3fb" stroke="#6485a9"/><text x="112" y="98" font-size="12" fill="#55708f">L40-EX01</text><text x="100" y="285" font-size="12" fill="#55708f">DB-EX03 / 12回路</text><text x="25" y="348" font-size="11" fill="#7b8aa0">図面の配置イメージです。実数量の自動計測結果ではありません。</text></svg>`}
async function updatePreview(id){const el=$('#sourcePreview');if(!el)return;const targetId=id||$('#previewSource')?.value,source=(w.documents||[]).find(d=>d.id===targetId)||docs().find(d=>d.id===targetId);if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=''}if(!source||source.sample){el.innerHTML=sampleDrawing();return}const stored=await store.getFile(source.id);if(!stored){el.innerHTML='<div class="empty">原本がこの端末にありません。再追加してください。</div>';return}previewUrl=URL.createObjectURL(stored.file);el.innerHTML=source.kind==='pdf'?`<object data="${previewUrl}" type="application/pdf"><a href="${previewUrl}" target="_blank" rel="noopener">PDFを開く</a></object>`:['png','jpg','jpeg'].includes(source.kind)?`<img src="${previewUrl}" alt="取込原本">`:`<div class="empty"><h3>表形式の原本</h3><p>明細候補は列の対応付けから取り込めます。</p>${button('parse-source','列を選んで取り込む','',`data-id="${source.id}"`)}</div>`;}
function requestItems(){const r=req(),i=currentItem();return `<div class="panel-grid"><article class="card"><div class="card-head"><h2>02　依頼明細を確認</h2>${badge(r.items.filter(i=>i.confirmed).length+' / '+r.items.length+' 確認済み')}</div><div class="table-wrap"><table class="line-table"><thead><tr><th></th><th>品名・型番</th><th>数量 / 単位</th><th>確認</th></tr></thead><tbody>${r.items.map((i,index)=>`<tr class="${i.id===selectedItem?'selected':''}" data-item="${i.id}"><td><span class="pill-number">${index+1}</span></td><td><strong>${esc(i.name)}</strong><small>${esc(i.model||'型番未確定')}</small></td><td>${num(i.qty)} ${esc(i.unit)}</td><td>${badge(i.confirmed?'確認済':'要確認',i.confirmed?'':'warn')}</td></tr>`).join('')}</tbody></table></div><div class="card-body">${button('add-item','＋ 明細を追加')}<p class="hint">行を選んで編集。変更した行は再確認が必要です。</p></div></article><article class="card"><div class="card-head"><h2>選択中の明細</h2>${i?button('remove-item','削除','text danger',`data-id="${i.id}"`):''}</div><div class="card-body">${i?`<div class="field-grid">${itemField('品名 *','name',i.name)}${itemField('メーカー','manufacturer',i.manufacturer)}${itemField('型番','model',i.model)}${itemField('要求仕様（型番不明なら必須）','spec',i.spec)}${itemField('数量 *','qty',i.qty,'number','min="0.001" step="0.001"')}${itemField('単位 *','unit',i.unit)}</div><details class="wire-details"><summary>電線の条件・適用銅ベース</summary><div class="field-grid">${itemField('電線種類','wireType',i.wireType||'')}${itemField('サイズ','size',i.size||'')}${itemField('芯数','cores',i.cores??'','number','min="1"')}${itemField('適用銅ベース（円/t）','copperBase',i.copperBase??'','number','min="0"')}${itemField('購入形態・切売り条件','packing',i.packing||'')}</div></details><p class="hint">原文型番：${esc(i.originalModel||'未登録')} / 正規化：${esc(norm(i.model))}</p><div class="request-check"><label class="check"><input type="checkbox" data-confirm-item="${i.id}" ${i.confirmed?'checked':''}>品名・数量・単位・仕様を確認した</label></div><p class="hint">根拠：${esc(i.reference||'手入力 / 原本を確認してください')}</p>${button('item-evidence','原本と照合','text',`data-id="${i.id}"`)}`:'<div class="empty">明細を追加して、品名・数量・単位を入力してください。</div>'}</div></article></div>${actions({action:'request-back',label:'← 資料に戻る'},button('request-next','依頼条件へ →','primary'))}`}
function itemField(label,name,value,type='text',extra=''){return `<label>${label}<input data-item-field="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function requestConditions(){const r=req();return `<div class="panel-grid"><article class="card"><div class="card-head"><h2>03　依頼先</h2>${button('add-vendor','＋ 仕入先を追加','text')}</div><div class="card-body stack">${w.vendors.map(v=>`<div class="file-row"><label class="check" style="flex:1"><input type="checkbox" data-vendor="${v.id}" ${r.vendorIds.includes(v.id)?'checked':''}>${esc(v.name)}</label><small>${esc(v.contact||'連絡先未登録')}</small>${button('edit-vendor','編集','text',`data-id="${v.id}"`)}</div>`).join('')}<p class="hint">依頼書を作成しただけでは送信されません。送信先・添付・内容の確認は別工程です。</p></div></article><article class="card"><div class="card-head"><h2>回答・納入条件</h2></div><div class="card-body"><div class="field-grid">${field('回答期限 *','deadline',r.conditions.deadline,'date')}${field('希望納期 *','needDate',r.conditions.needDate,'date')}${field('納入先 *','destination',r.conditions.destination)}${field('送料・分納条件','shipping',r.conditions.shipping)}<label class="wide">備考<textarea data-field="notes">${esc(r.conditions.notes)}</textarea></label><label class="check wide"><input type="checkbox" data-field="allowAlternative" ${r.conditions.allowAlternative?'checked':''}>代替品は仕様差を明示して別途回答</label></div><div class="mini-summary" style="margin-top:22px"><div><span>仕入履歴</span><strong>${w.history.length}件</strong></div><div><span>次案件の使用予定</span><strong>${w.usagePlans.length}件</strong></div><div><span>販売単価</span><strong>${r.items.some(i=>i.saleUnit>0)?'対応する品目のみ連携':'未連携・粗利は未算出'}</strong></div></div></div></article></div>${actions({action:'request-back',label:'← 明細に戻る'},button('request-next','依頼内容をプレビュー →','primary'))}`}
function requestPreview(){const r=req(),errors=validateRequest(r);return `<div class="panel-grid"><article class="card"><div class="card-head"><h2>04　依頼内容の確認</h2>${badge('第'+r.version+'版','neutral')}</div><div class="card-body"><h3>${esc(project(r)?.name)}</h3><p class="hint">${esc(r.number)} / 回答期限 ${esc(r.conditions.deadline)} / 希望納期 ${esc(r.conditions.needDate)}<br>納入先 ${esc(r.conditions.destination)}</p></div>${table(['品名 / 型番','数量','要求仕様'],r.items.map(i=>[esc(i.name)+'<small>'+esc(i.model||'型番未確定')+'</small>',num(i.qty)+' '+esc(i.unit),esc(i.spec)]))}<div class="card-body"><p class="hint">${esc(r.conditions.notes)}<br>${esc(r.conditions.shipping)}</p></div></article><article class="card"><div class="card-head"><h2>作成する内容</h2></div><div class="card-body stack"><div class="mini-summary"><div><span>依頼明細</span><strong>${r.items.length}品目</strong></div><div><span>依頼先</span><strong>${r.vendorIds.map(v=>esc(vendor(v))).join('・')}</strong></div><div><span>添付原本</span><strong>${r.sourceIds.length}資料</strong></div></div><p class="hint">作成物は依頼書PDF・回答用Excel・依頼文の下書きです。他社の回答金額・仕入原価は含めません。</p>${errors.length?`<div class="issue-box">${errors.map(e=>'・'+esc(e)).join('<br>')}</div>`:badge('明細・依頼条件の確認が完了')}${button('request-pdf','依頼書をプレビュー')}${button('response-template','回答用Excelを出力')}${button('request-text','依頼文の下書き')}</div></article></div>${actions({action:'request-back',label:'← 条件に戻る'},button('create-request','見積依頼を作成 →','primary') )}`}
function allVendor(r,v){return comparison(r,Object.fromEntries(r.items.map(i=>[i.id,v])),today())}
function renderCompare(){const r=req(),c=comparison(r,r.selected,today()),issue=c.issues,chosen=currentItem(),advice=recommendations(w,r,chosen?.id,today());return `<div class="compare-layout"><div class="compare-main"><article class="card"><div class="card-head"><div class="inline"><h2>見積比較</h2>${badge(Object.keys(r.responses).length+'社 回答')}</div><div class="inline">${button('optimize','送料込み最安を選ぶ','text')}${button('import-response','回答見積を取り込む')}</div></div><div class="table-wrap"><table class="compare-table"><thead><tr><th>品目・数量</th>${r.vendorIds.map(v=>`<th>${esc(vendor(v))}<br>${button('edit-response','回答を確認','text',`data-id="${v}"`)}</th>`).join('')}</tr></thead><tbody>${r.items.map(i=>{const min=Math.min(...r.vendorIds.map(v=>r.responses[v]?.lines[i.id]?.unit??Infinity));return `<tr><td><button class="text" data-action="select-item" data-id="${i.id}" style="text-align:left"><strong>${esc(i.name)}</strong><small>${esc(i.model)} · ${num(i.qty)}${esc(i.unit)}</small></button></td>${r.vendorIds.map(v=>{const q=r.responses[v],l=q?.lines[i.id],chosen=r.selected[i.id]===v;return `<td class="${chosen?'chosen':''}">${!l||!l.available?'<small>未回答 / 対応不可</small>':`<button class="quote-cell" data-action="select-quote" data-id="${i.id}" data-vendor="${v}" aria-label="${esc(i.name+'：'+vendor(v)+'を選択')}" aria-pressed="${chosen}"><span class="radio-dot">${chosen?'✓':''}</span><span><span class="quote-price">${yen(l.unit)}${l.unit===min?'<span class="cheapest">単価最安</span>':''}</span><span class="total-line">${yen(amount(l.unit,i.qty))}</span><small>${l.leadDays}日 / ${!l.confirmed?'回答要確認':!l.specMatch?'仕様差あり':q.validUntil<today()?'期限切れ':'確認済み'}</small></span></button>`}</td>`}).join('')}</tr>`}).join('')}${['商品合計','送料','1社一括の総額','納期 / 有効期限'].map((label,index)=>`<tr class="sum-row ${index===2?'total':''}"><td>${label}</td>${r.vendorIds.map(v=>{const a=allVendor(r,v),q=r.responses[v];return `<td>${!q?'—':index===0?yen(a.goods):index===1?q.freight.confirmed?yen(a.freight):'未確認':index===2?a.total===null?'未確定':yen(a.total):a.maxLead+'日 / '+esc(q.validUntil.slice(5))}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="selected-total"><div><span>品目別の選択総額（税抜・送料込）</span><strong>${c.total===null?'総額未確定':yen(c.total)}</strong></div><div class="saving">${r.baseline?esc(r.baseline.label)+'比 '+(c.saved===null?'未確定':(c.saved>=0?'−':'＋')+yen(Math.abs(c.saved))):'比較基準 未設定'}</div></div><div class="compare-note">単価最安の印と、送料込み全体最安は別です。送料は仕入先単位で集計。 ${button('baseline','比較基準を確認・固定','text')}</div></article>${issue.length?`<div class="issue-box"><strong>採用前に確認が必要な条件</strong><br>${issue.map(e=>'・'+esc(e)).join('<br>')}</div>`:''}<article class="card"><div class="history-head"><h2>選択品目の履歴</h2><select id="historyItem">${r.items.map(i=>`<option value="${i.id}" ${i.id===chosen?.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select></div>${historyTable(chosen)}<div class="card-body"><p class="hint">同じメーカー・型番・仕様・単位の履歴です。数量と時期の違いを確認してください。${chosen?.list>0&&r.responses[r.selected[chosen.id]]?.lines[chosen.id]?'<br>当時定価 '+yen(chosen.list)+' / 今回掛け率 '+(r.responses[r.selected[chosen.id]].lines[chosen.id].unit/chosen.list*100).toFixed(1)+'%':''}</p></div></article></div><aside class="card insights"><div class="card-head"><h2>取引データから、次の一手</h2></div><div class="insight-tabs">${button('insight-suggestions','次の一手',insightTab==='suggestions'?'active':'')}${button('insight-chat','データに質問',insightTab==='chat'?'active':'')}</div><div class="insight-body ${insightTab==='suggestions'?'suggestion-mode':''}">${insightTab==='chat'?renderChat():advice.length?advice.slice(0,w.settings.maxSuggestions).map(a=>`<article class="suggestion-mini"><div class="inline spread"><span class="eyebrow">${a.rule}</span>${badge(a.status,'neutral')}</div><h3>${esc(a.title)}</h3><p>${esc(a.body)}</p>${a.effect!==null?`<div class="effect">交渉余地 ${yen(a.effect)}</div><small>未成立の試算・採用額に含めません</small>`:''}<p>${a.evidence.map(e=>'▤ '+esc(e)).join('<br>')}</p>${button('suggestion-detail','根拠・実行内容を見る','',`data-id="${a.id}"`)}</article>`).join(''):'<div class="insight-empty">比較条件を確認できる履歴が不足しています。履歴・次案件の数量を追加すると、根拠のある提案だけを表示します。</div>'}</div><div class="card-body" style="padding-top:0"><p class="hint">${chosen?.saleUnit>0?'対応する売価がある品目のみ材料粗利を計算。':'販売単価は未連携。粗利額・率は未算出です。'}</p>${button('add-plan','＋ 次案件の使用予定','text')}<br>${button('link-sales','販売単価を対応付ける','text')}${chosen?.unit==='m'?`<div class="mini-summary" style="margin-top:15px"><h3>適用銅ベース</h3><p class="hint">今回 ${chosen.copperBase>0?yen(chosen.copperBase)+'/t':'未登録'}<br>最新記録 ${(w.copper||[]).length?yen(w.copper.at(-1).value)+'/t / '+w.copper.at(-1).date:'未登録'}<br>基準の異なる過去単価は交渉目安に使いません。</p></div>`:''}</div></aside></div>${actions({action:'back-request',label:'← 依頼内容を見る'},button('review-adopt','採用内容を確認 →','primary'))}`}
function historyTable(i){if(!i)return '<div class="empty">品目を選択してください。</div>';const rows=historyFor(w,i);return rows.length?table(['購入日','数量','単価 / 掛け率','仕入先・根拠'],rows.map(h=>[esc(h.date),num(h.qty)+esc(h.unitLabel),yen(h.unit)+'<small>'+(h.list>0?(h.unit/h.list*100).toFixed(1)+'% / 当時定価 '+yen(h.list):'定価不明')+'</small>',esc(vendor(h.vendorId))+'<small>'+esc(h.source)+'</small>'])):'<div class="empty"><p>条件の合う履歴がありません。原本と購入条件を追加してください。</p></div>';}
function renderChat(){const r=req();return `<div class="chat-log">${(r.chat||[]).map(m=>`<div class="chat-message ${m.role==='user'?'user':''}">${esc(m.text)}${m.evidence?.length?`<span class="evidence">根拠：${m.evidence.map(esc).join(' / ')}</span>`:''}</div>`).join('')||'<div class="chat-message">確認済みの履歴・回答・次案件の予定を参照します。過去価格、数量条件、送料について質問できます。</div>'}</div><div class="chat-prompts">${['過去はいくら？','まとめて交渉できる？','送料の条件は？'].map(t=>button('chat-prompt',t,'',`data-text="${t}"`)).join('')}</div><div class="chat-input"><input id="chatQuestion" placeholder="選択品目の取引条件を質問…" maxlength="300"><button data-action="chat-send" class="primary" aria-label="質問を送信">➤</button></div><p class="hint">確認済みデータからの定型回答です。未確認の価格は補完しません。</p>`}
function renderAdopt(){const r=req(),a=r.adoptions.at(-1);if(a&&r.status==='採用確定')return renderConfirmed(a);const c=comparison(r,r.selected,today());return `<div class="adoption-layout"><div class="adoption-left"><article class="card"><div class="card-head"><h2>採用明細</h2>${button('back-compare','比較画面で変更','text')}</div>${table(['採用品目','数量','採用先','単価 / 金額','納期'],r.items.map(i=>{const v=r.selected[i.id],l=r.responses[v]?.lines[i.id];return[esc(i.name)+'<small>'+esc(i.model)+' / '+esc(i.spec)+'</small>',num(i.qty)+esc(i.unit),badge(vendor(v),'blue'),l?yen(l.unit)+'<small>'+yen(amount(l.unit,i.qty))+'</small>':'未選択',l?l.leadDays+'日':'—']}))}</article><article class="card"><div class="card-head"><h2>仕入先別の発注明細</h2></div>${groupTable(c)}</article><article class="card"><div class="card-head"><h2>確定前の確認</h2></div><div class="checklist">${['型番・数量・単位・仕様を確認','送料・分納条件・納期を確認','回答版・見積有効期限を確認'].map((t,i)=>`<label class="check"><input type="checkbox" data-adopt-check="${i}" ${r.confirmChecks?.[i]?'checked':''}>${t}</label>`).join('')}</div><div class="card-body" style="padding-top:0"><p class="hint">納入先 ${esc(r.conditions.destination)} / 希望納期 ${esc(r.conditions.needDate)}<br>採用確定だけでは依頼・発注を送信しません。</p></div></article></div><aside class="card"><div class="card-head"><h2>採用金額</h2></div><div class="card-body">${amountSummary(c)}${materialMargin(r,c)?`<div class="summary-green">材料粗利 ${yen(materialMargin(r,c).profit)} / ${materialMargin(r,c).rate.toFixed(1)}%</div>`:''}${c.issues.length?`<div class="issue-box" style="margin-top:18px">${c.issues.map(esc).join('<br>')}</div>`:''}<p class="hint">交渉による追加効果は未確定。販売単価が連携された品目だけ材料粗利を確認できます。</p>${button('finalize','採用を確定して明細を作成 →','primary','style="width:100%;margin-top:22px"')}<p class="hint">確定後の変更は改訂版として保存します。</p></div></aside></div>${actions({action:'back-compare',label:'← 金額比較に戻る'},button('save','下書き保存'))}`}
function amountSummary(c){return `<div class="amount-row"><span>商品金額</span><strong>${yen(c.goods)}</strong></div><div class="amount-row"><span>値引き</span><strong>−${yen(c.discount)}</strong></div><div class="amount-row"><span>送料等</span><strong>${Object.values(c.groups).some(g=>g.freight===null)?'未確定':yen(c.freight)}</strong></div><div class="amount-row summary-highlight"><span>合計（税抜）</span><strong class="big-amount">${c.total===null?'未確定':yen(c.total)}</strong></div><div class="summary-green">比較基準からの削減額<strong>${yen(c.saved)}</strong></div><p class="hint">最長納期 ${c.maxLead}日。未成立の提案は合計に含めません。</p>`}
function groupTable(c){return table(['仕入先','品目数','商品金額','送料','総額'],Object.values(c.groups).map(g=>[esc(vendor(g.vendorId)),g.items.length+'品目',yen(g.goods),yen(g.freight),yen(g.total)]))}
function renderConfirmed(a){const r=req();return `<div class="success-panel"><div class="inline spread"><div><span class="eyebrow">ADOPTION CONFIRMED / VERSION ${a.version}</span><h2>採用を確定しました。</h2><p>仕入先別の発注明細と予定原価 ${yen(a.plannedCost)} を保存済み。発注は未送信です。</p></div>${badge('第'+a.version+'版・確定')}</div></div><nav class="tab-pills">${['orders','receipts','results','versions'].map((s,i)=>button('after-tab',['発注明細・出力','納品・請求の照合','交渉結果','採用の版履歴'][i],afterTab===s?'active':'',`data-tab="${s}"`)).join('')}</nav>${afterTab==='receipts'?renderReconciliation(a):afterTab==='results'?renderResults():afterTab==='versions'?`<article class="card">${table(['採用版','確定日時','予定原価','状態'],r.adoptions.map(x=>[x.version,esc(new Date(x.createdAt).toLocaleString('ja-JP')),yen(x.plannedCost),button('show-version','詳細を見る','text',`data-id="${x.id}"`)]))}</article>`:`<div class="adoption-layout"><article class="card"><div class="card-head"><h2>仕入先別の発注明細</h2>${badge('未送信','neutral')}</div>${groupTable(a.comparison)}<div class="card-body"><div class="inline">${button('order-doc','発注書を作成','primary')}${button('adoption-xlsx','Excel出力')}${button('adoption-csv','他サイト取込CSV')}</div><p class="hint">納入先 ${esc(a.conditions.destination)} / 希望納期 ${esc(a.conditions.needDate)}<br>CSVは共通形式です。取込先で列を対応付けてください。</p></div></article><aside class="card"><div class="card-head"><h2>確定した原価</h2></div><div class="card-body">${amountSummary(a.comparison)}<p class="hint">実購入原価は納品・請求の照合後に確定します。</p></div></aside></div>`}${actions({action:'revise',label:'← 改訂版を作って変更'},button('projects','現場・依頼一覧へ'))}`}
function renderReconciliation(a){const r=req(),entries=r.invoiceEntries||[],results=reconcile(a,entries,w.settings.differenceYen);return `<article class="card"><div class="card-head"><h2>発注・納品・請求を照合</h2>${button('add-invoice','＋ 納品・請求行を追加','primary')}</div><div class="card-body">${r.actualSummary?.complete?`<div class="summary-green">照合済みの実購入原価 <strong>${yen(r.actualSummary.actualCost)}</strong></div>`:''}<p class="hint">分納は累計数量で照合。税抜金額で比較し、承認済み変更額は差額から除外します。請求額を自動修正しません。</p></div>${results.length?table(['品目','累計数量','実購入本体','未説明差額','状態・根拠'],results.map(x=>[esc(r.items.find(i=>i.id===x.itemId)?.name),num(x.qty)+' / '+num(x.expectedQty),yen(x.goods),yen(x.delta),badge(x.status,x.status==='確認待ち'?'warn':x.status==='照合済み'?'':'neutral')+'<small>'+esc(x.source)+'</small>'])):'<div class="empty"><p>納品・請求の明細を追加すると、発注時点の条件との差を確認できます。</p></div>'}<div class="card-body">${entries.length?table(['登録日','原本・行','単価×数量','追加送料','操作'],entries.map(e=>[esc(e.date),esc(e.source),yen(e.unit)+' × '+num(e.qty),yen(e.freight),button('remove-invoice','行を削除','text',`data-id="${e.id}"`)])):''}</div></article>`}
function renderResults(){const r=req();const list=Object.entries(r.proposalResults);return `<article class="card"><div class="card-head"><h2>提案の採否・交渉結果</h2></div>${list.length?table(['検討テーマ','状態','理由・成立条件','最終単価'],list.map(([id,x])=>[esc(x.title||id),badge(x.status,x.status==='成立'?'':'neutral'),esc(x.reason||'未記録'),x.finalUnit===null?'未確定':yen(x.finalUnit)])):'<div class="empty">比較画面の「次の一手」から実行・結果を記録してください。</div>'}<div class="card-body"><p class="hint">成立価格は確認済みの回答見積へ新しい版として登録してから採用します。当初試算・過去の採用版は残します。</p></div></article>`}
function renderHistoryPage(){return `<div class="inline spread" style="margin-bottom:20px"><h2>商品・価格履歴</h2><div class="inline">${button('import-history','Excel・CSVから取込')}${button('add-history','＋ 履歴を追加')}</div></div><article class="card">${w.history.length?table(['購入日','品名・型番','数量','単価','当時定価 / 掛け率','仕入先・原本'],w.history.map(h=>[esc(h.date),esc(h.model)+'<small>'+esc(h.spec)+'</small>',num(h.qty)+esc(h.unitLabel),yen(h.unit),yen(h.list)+'<small>'+(h.list>0?(h.unit/h.list*100).toFixed(1)+'%':'未算出')+'</small>',esc(vendor(h.vendorId))+'<small>'+esc(h.source)+'</small>'])):'<div class="empty">仕入履歴を追加してください。</div>'}</article><p class="hint">当時の単価・定価を保存し、後日の価格改定で過去の掛け率を上書きしません。</p>`}
function renderMarket(){return `<div class="inline spread" style="margin-bottom:20px"><h2>価格改定情報</h2>${button('add-notice','＋ 公式案内を登録')}</div><article class="card" style="margin-bottom:22px"><div class="card-head"><h2>国内銅建値（円/t）</h2>${button('add-copper','＋ 基準値・根拠を登録','text')}</div>${(w.copper||[]).length?table(['基準日','銅ベース','根拠'],w.copper.map(c=>[esc(c.date),yen(c.value)+'/t',esc(c.source)])):'<div class="empty">銅ベースは未登録です。公式の基準日・単位・根拠を記録してください。</div>'}<div class="card-body"><p class="hint">銅の変動率を電線単価へ直接換算しません。見積時点の適用基準は各明細に保存します。</p></div></article><div class="page-alert">発表日と適用日、定価と仕入価格を区別します。定価改定だけでは仕入影響額を算出しません。最新情報の自動収集はこの画面には未接続です。</div><div class="project-cards">${w.notices.map(n=>`<article class="card project-card"><div class="inline spread">${badge(n.kind+'改定','warn')}<small>${esc(n.model)}</small></div><h3>価格改定 ＋${n.rate}%</h3><p>発表 ${esc(n.announced)}<br>適用 ${esc(n.effective)} / ${esc(n.basis)}基準<br>根拠：${esc(n.source)}</p><div class="inline">${badge(n.applied?'定価反映済み':n.confirmed?'確認済み・適用待ち':'要確認',n.applied?'':'neutral')}${n.kind==='定価'&&!n.applied?button('apply-notice','適用日を確認して反映','text',`data-id="${n.id}"`):''}</div></article>`).join('')||'<article class="card empty">価格改定案内を登録してください。</article>'}</div>`}
function renderSettings(){return `<article class="card"><div class="card-head"><h2>判定ルールの初期値</h2></div><div class="card-body"><div class="settings-grid">${[['historyMonths','履歴参照期間（月）'],['minRecords','傾向を表示する最小件数'],['nextDays','次案件との納期差（日）'],['marginPoints','粗利率の差（pt）'],['revisionDays','改定前の確認期間（日）'],['differenceYen','未説明差額の検知（円）'],['maxSuggestions','次の一手の最大表示件数']].map(([k,label])=>`<label>${label}<input type="number" data-setting="${k}" value="${w.settings[k]}" min="1" max="${k==='maxSuggestions'?3:365}"></label>`).join('')}</div></div></article><article class="card" style="margin-top:22px"><div class="card-head"><h2>データ・保存と対応範囲</h2></div><div class="card-body stack"><p>原本と取引は端末内のIndexedDBに保存します。サンプルと自分のデータは別領域です。JSONは取引データのみです。ブラウザのデータ消去に備え、原本ファイルは別途保管してください。</p><div class="inline">${button('backup','JSONバックアップ')}${button('restore-open','バックアップを復元')}${button('support','機能の対応範囲')}<a href="simple-demo.html">以前のデモと保存明細 ↗</a></div><div class="page-alert">会社別ログイン・サーバーでの権限管理、クラウド原本共有、OCR、メール/API送信、他サービスへの直接連携は未接続です。本画面は単独利用の業務プロトタイプとして動作します。</div><p class="hint">操作履歴 ${w.audit.length}件 / 保存版 ${w.revision} / データ区分 ${w.mode==='sample'?'サンプル':'自分のデータ'}</p></div></article>`}
function invalidate(){const r=req();if(!r)return;for(const x of Object.values(r.proposalResults))if(x.status!=='成立')x.needsReview=true;if(r.adoptions.length)r.status='編集中';r.updatedAt=new Date().toISOString();}
function download(name,body,type){const url=URL.createObjectURL(body instanceof Blob?body:new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),15000)}
function printDocument(){document.body.classList.add('print-doc');window.print()}
function paper(title,subtitle,rows,heads,footer=''){return `<article class="document-paper"><h2>${title}</h2><p>${subtitle}</p>${table(heads,rows)}${footer}</article>`}
function requestPaper(){const d=requestDocument(w,req());return paper('見積依頼書',`${esc(d.project)} / ${esc(d.number)} 第${d.version}版<br>回答期限 ${esc(d.conditions.deadline)} / 希望納期 ${esc(d.conditions.needDate)}<br>納入先 ${esc(d.conditions.destination)}`,d.items.map(i=>[esc(i.name),esc(i.model||'型番未確定'),esc(i.spec),num(i.qty),esc(i.unit)]),['品名','型番','仕様','数量','単位'],`<p>${esc(d.conditions.shipping)}<br>${esc(d.conditions.notes)}</p><p>単価・金額・送料・有効期限・納期を明示してご回答ください。代替品は仕様差を別途明示してください。</p>`)}
function showPaper(title,body){modal(title,body+`<div class="modal-actions no-print">${button('print','印刷 / PDF保存','primary')}</div>`)}
async function excel(name,heads,rows){const {tableWorkbook}=await import('./rfq-export.bundle.js');download(name,await tableWorkbook(heads,rows),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')}
function adoptionRows(a){return Object.values(a.comparison.groups).flatMap(g=>g.items.map(i=>[project(req())?.name,vendor(g.vendorId),i.name,i.manufacturer,i.model,i.spec,i.qty,i.unit,i.unitPrice,i.lineAmount,g.freight,g.discount,g.total,a.version,a.conditions.needDate,a.conditions.destination]));}
const exportHeads=['案件名','仕入先','品名','メーカー','型番','仕様','数量','単位','税抜単価','税抜明細金額','送料_仕入先単位','値引き_仕入先単位','仕入先総額','採用版','希望納期','納入先'];
function groupExportRows(a){return Object.values(a.comparison.groups).flatMap(g=>g.items.map((i,index)=>[project(req())?.name,vendor(g.vendorId),i.name,i.manufacturer,i.model,i.spec,i.qty,i.unit,i.unitPrice,i.lineAmount,index===0?g.freight:'',index===0?g.discount:'',index===0?g.total:'',a.version,a.conditions.needDate,a.conditions.destination]));}
function orderPaper(a){return Object.values(a.comparison.groups).map(g=>paper('発注書（下書き・未送信）',`${esc(vendor(g.vendorId))} 御中<br>${esc(project(req())?.name)} / ${esc(req().number)} 採用第${a.version}版<br>納入先 ${esc(a.conditions.destination)} / 希望納期 ${esc(a.conditions.needDate)}`,g.items.map(i=>[esc(i.name)+'<small>'+esc(i.model)+' / '+esc(i.spec)+'</small>',num(i.qty)+esc(i.unit),yen(i.unitPrice),yen(i.lineAmount)]),['品名・型番・仕様','数量','単価（税抜）','明細金額'],`<p>配送条件：${esc(a.conditions.shipping)}<br>送料 ${yen(g.freight)} / 値引き −${yen(g.discount)}</p><p class="paper-total">税抜合計 ${yen(g.total)}</p><p>消費税は別途、取引条件に従い計算。発注前に送付先・添付資料・有効期限を確認してください。</p>`)).join('')}
async function handle(action,b){const r=req();switch(action){
 case 'new':modal('NEW REQUEST',`<h2>現場と依頼を作成</h2><form id="newForm"><div class="field-grid"><label>既存の現場<select name="existing"><option value="">新しい現場を作る</option>${w.projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>新しい現場名<input name="name" maxlength="100" placeholder="例：大阪工場 電気設備工事"></label></div><div class="modal-actions"><button class="primary">資料の取込へ →</button></div></form>`);break;
 case 'project-ledger':showProjectLedger(b.dataset.id);break;
 case 'project-export':{const rows=projectLedgerRows(b.dataset.id);await excel('現場別採用明細.xlsx',['現場名','依頼番号','採用版','仕入先','品名','型番','数量','単位','税抜単価','税抜本体','送料_仕入先単位','値引き_仕入先単位','仕入先総額'],rows);break;}
 case 'projects':case 'requests':stage='projects';render();break;
 case 'open-request':requestId=b.dataset.id;stage=req().status==='下書き'?'request':req().status==='採用確定'?'adopt':'compare';substep=req().step||0;render();break;
 case 'request-step':await goRequest(Number(b.dataset.step));break;
 case 'request-next':await goRequest(substep+1);break;
 case 'request-back':substep=Math.max(0,substep-1);r.step=substep;await commit();render();break;
 case 'back-request':stage='request';substep=3;render();break;
 case 'back-compare':stage='compare';render();break;
 case 'save':await commit('下書き保存');toast('下書きを保存しました');break;
 case 'add-item':{const id=uid();r.items.push({id,name:'新しい品目',model:'',originalModel:'',normalizedModel:'',manufacturer:'',qty:1,unit:'台',spec:'',list:0,confirmed:false,reference:'手入力',updatedAt:new Date().toISOString()});selectedItem=id;invalidate();await commit('明細追加');render();break}
 case 'remove-item':if(r.items.length&&confirm('選択した明細を削除しますか？確定済みの旧版は残ります。')){r.items=r.items.filter(i=>i.id!==b.dataset.id);delete r.selected[b.dataset.id];invalidate();await commit('明細削除');render()}break;
 case 'add-vendor':case 'edit-vendor':{const v=w.vendors.find(v=>v.id===b.dataset.id);modal('SUPPLIER',`<h2>${v?'仕入先を編集':'仕入先を追加'}</h2><form id="vendorForm" data-id="${v?.id||''}"><div class="field-grid"><label>仕入先名<input name="name" value="${esc(v?.name||'')}" required maxlength="100"></label><label>連絡先<input name="contact" value="${esc(v?.contact||'')}" maxlength="200"></label></div><div class="modal-actions"><button class="primary">保存</button></div></form>`);break}
 case 'preview-source':{const d=(w.documents||[]).find(x=>x.id===b.dataset.id)||docs().find(x=>x.id===b.dataset.id);if(!d)throw Error('この根拠は参照情報です。原本ファイルは未登録です');modal('SOURCE / 原本',`<h2>${esc(d.name)}</h2><div class="drawing"><div id="sourcePreview"></div></div><p class="hint">${d.hash?'SHA-256 '+esc(d.hash):'操作用サンプル / 自動読取結果ではありません'}</p>`);await updatePreview(d.id);break}
 case 'parse-source':await importSource(b.dataset.id);break;
 case 'remove-source':r.sourceIds=r.sourceIds.filter(id=>id!==b.dataset.id);await commit('原本の紐付け解除');render();break;
 case 'item-evidence':{const i=currentItem();modal('SOURCE EVIDENCE',`<h2>${esc(i.name)}の根拠</h2><p>${esc(i.reference||'手入力・原本未登録')}</p><p>原文型番 ${esc(i.originalModel||'未登録')} / 現在 ${esc(i.model||'型番未確定')}</p><div class="drawing"><div id="sourcePreview"></div></div>`);await updatePreview(i.sourceId);break}
 case 'request-pdf':showPaper('REQUEST DOCUMENT',requestPaper());break;
 case 'response-template':await excel('回答用_'+r.number+'.xlsx',['型番','品名','仕様','数量','単位','単価','金額','納期日数','有効期限','仕様差'],r.items.map(i=>[i.model,i.name,i.spec,i.qty,i.unit,'','','','','']));break;
 case 'request-text':modal('REQUEST DRAFT',`<h2>依頼文の下書き</h2><textarea id="requestText" style="width:100%;height:230px">${esc(`${r.vendorIds.map(v=>vendor(v)+' 御中').join('\n')}\n\n${project(r)?.name}につき、添付明細のお見積をお願いいたします。\n回答期限：${r.conditions.deadline}\n希望納期：${r.conditions.needDate}\n納入先：${r.conditions.destination}\n${r.conditions.shipping}\n${r.conditions.notes}\n\n単価・金額・送料・納期・有効期限を分けてご回答ください。`)}</textarea><p class="hint">下書きです。実際の送信は行いません。</p>`);break;
 case 'create-request':{const errors=validateRequest(r);if(errors.length)throw Error(errors.join(' / '));r.status='依頼書作成済';r.requestDocument=requestDocument(w,r);await commit('依頼書作成');modal('REQUEST CREATED',`<h2>見積依頼を作成しました。</h2><p>依頼番号 ${esc(r.number)} / 第${r.version}版。依頼条件と明細を保存しました。まだ送信されていません。</p><div class="inline">${button('request-pdf','依頼書PDF')}${button('response-template','回答用Excel')}</div><div class="modal-actions">${button('mark-requested','外部で依頼したことを記録 →','primary')}</div><p class="hint">メールや既存の方法で依頼後に記録してください。次の画面で回答を取り込めます。</p>`);break}
 case 'mark-requested':r.status='回答受付中';r.requestedAt=new Date().toISOString();await commit('外部依頼を手動記録');closeModal();stage='compare';render();break;
 case 'select-item':selectedItem=b.dataset.id;render();break;
 case 'select-quote':r.selected[b.dataset.id]=b.dataset.vendor;invalidate();await commit('採用候補変更');render();break;
 case 'optimize':{const result=optimize(r,today());if(!result.selection)throw Error(result.reason);r.selected=result.selection;r.optimization={complete:result.complete,visits:result.visits,total:result.total};invalidate();await commit('送料込み最安探索');render();toast((result.complete?'全組み合わせを確認した最安':'探索未完了の最安候補')+'：'+yen(result.total));break}
 case 'baseline':modal('FIXED BASELINE',`<h2>比較基準を固定</h2><p>現在の基準：${r.baseline?esc(r.baseline.label)+' / '+yen(r.baseline.amount):'未設定'}。比較中の選択を変えても、この金額は動かしません。</p><div class="stack">${r.vendorIds.map(v=>button('set-baseline',vendor(v)+' 一括 / '+yen(allVendor(r,v).total),'',`data-id="${v}"`)).join('')}</div>`);break;
 case 'set-baseline':fixBaseline(r,b.dataset.id,today());r.baseline.label=vendor(b.dataset.id)+' 一括';await commit('比較基準固定');closeModal();render();break;
 case 'edit-response':showResponseForm(b.dataset.id);break;
 case 'import-response':showImportPicker('response');break;
 case 'select-response-file':await readImportFile($('#importFile').files[0],'response');break;
 case 'import-history':showImportPicker('history');break;
 case 'import-commit':await commitImport();break;
 case 'insight-suggestions':insightTab='suggestions';render();break;
 case 'insight-chat':insightTab='chat';render();break;
 case 'chat-prompt':await askData(b.dataset.text);break;
 case 'chat-send':await askData($('#chatQuestion').value);break;
 case 'suggestion-detail':showSuggestion(b.dataset.id);break;
 case 'negotiation-draft':await createNegotiationDraft(b.dataset.id);break;
 case 'candidate-supplier':{const a=recommendations(w,r,currentItem().id,today()).find(a=>a.id===b.dataset.id);if(!a?.vendorId||!w.vendors.some(v=>v.id===a.vendorId))throw Error('仕入先情報を追加してください');r.vendorIds=[...new Set([...r.vendorIds,a.vendorId])];await commit('追加依頼の仕入先候補を保存');closeModal();stage='request';substep=2;render();break;}
 case 'add-plan':showPlan();break;
 case 'link-sales':showSales();break;
 case 'review-adopt':stage='adopt';render();break;
 case 'finalize':{await commit('採用確定前の保存');const a=finalize(w,req(),req().confirmChecks||[],today());await commit('採用確定 / 第'+a.version+'版');render();toast('採用第'+a.version+'版と予定原価を保存しました');break}
 case 'after-tab':afterTab=b.dataset.tab;render();break;
 case 'order-doc':showPaper('PURCHASE ORDER / 発注書の下書き',orderPaper(r.adoptions.at(-1)));break;
 case 'adoption-xlsx':await excel('発注明細_'+r.number+'.xlsx',exportHeads,groupExportRows(r.adoptions.at(-1)));break;
 case 'adoption-csv':{const {csvText}=await import('./rfq-export.bundle.js');download('発注明細_'+r.number+'.csv',csvText(exportHeads,groupExportRows(r.adoptions.at(-1))),'text/csv;charset=utf-8');break}
 case 'revise':r.status='編集中';r.version++;r.confirmChecks=[];await commit('採用の改訂開始 / 旧確定版を保持');stage='compare';render();break;
 case 'show-version':{const a=r.adoptions.find(a=>a.id===b.dataset.id);showPaper('ARCHIVED ADOPTION / 旧版',orderPaper(a));break}
 case 'add-invoice':showInvoice();break;
 case 'remove-invoice':r.invoiceEntries=r.invoiceEntries.filter(e=>e.id!==b.dataset.id);r.reconciliations=reconcile(r.adoptions.at(-1),r.invoiceEntries,w.settings.differenceYen);r.actualSummary=actualSummary(r.adoptions.at(-1),r.invoiceEntries,w.settings.differenceYen);await commit('照合行削除');render();break;
 case 'add-history':showHistoryForm();break;
 case 'add-notice':showNoticeForm();break;
 case 'add-copper':showCopperForm();break;
 case 'apply-notice':{const n=w.notices.find(n=>n.id===b.dataset.id);if(n.effective>today())throw Error('適用日は '+n.effective+' です。現時点の定価は変更しません。');if(!n.confirmed)throw Error('改定根拠を確認してください');const old=w.listHistory.filter(h=>h.model===n.model&&h.end===null).at(-1);if(!old)throw Error('改定元の定価が未登録です');old.end=n.effective;w.listHistory.push({id:uid(),model:n.model,price:amount(old.price,1+n.rate/100),start:n.effective,end:null,source:n.source});n.applied=true;await commit('確認済み定価の適用 / 過去履歴は保持');render();break}
 case 'print':printDocument();break;
 case 'backup':download('gaina-rfq-backup.json',JSON.stringify(w,null,2),'application/json');break;
 case 'restore-open':modal('RESTORE BACKUP',`<h2>バックアップを復元</h2><p>現在の${w.mode==='sample'?'サンプル':'自分の'}データを置き換えます。同じデータ区分のJSONのみ対応します。</p><input id="restoreFile" type="file" accept=".json"><div class="modal-actions">${button('restore','選択したJSONを復元','primary')}</div>`);break;
 case 'restore':{const file=$('#restoreFile').files[0];if(!file)throw Error('JSONを選択してください');if(file.size>5e6)throw Error('5MB以下のJSONを選択');const next=JSON.parse(await file.text());validateWorkspace(next);if(next.mode!==w.mode)throw Error('データ区分が一致しません');next.revision=w.revision;w=next;requestId=w.requests[0]?.id;await commit('バックアップ復元');closeModal();render();break}
 case 'support':modal('IMPLEMENTATION SCOPE',`<h2>このアプリでできること</h2><p>依頼の段階入力、原本の端末保存、Excel・CSVの列対応、明細・回答確認、送料込み組み合わせ探索、根拠付き次の一手、採用の版管理、発注明細・Excel出力、分納・請求照合、結果の保存に対応しています。</p><h3>接続が必要なもの</h3><p>PDF・画像OCR、メール・発注送信、会社別ログイン・権限、クラウドでの原本共有・複数端末連携、最新価格の自動収集は未接続です。AIチャットは確認済みデータからの定型回答です。</p><p>数量は小数、金額は税抜・円未満2桁まで。消費税の計算・端数照合は取引条件と別途確認してください。</p><a href="../docs/rfq-implementation.md" target="_blank" rel="noopener">実装項目・判定ルール・制約を見る ↗</a>`);break;
 default:throw Error('操作が見つかりません：'+action);
}}
async function goRequest(step){const r=req();if(step>=2){const errors=r.items.length?r.items.filter(i=>!i.confirmed||!i.name.trim()||!(i.qty>0)||!i.unit.trim()||!i.model.trim()&&!i.spec.trim()).map(i=>i.name+'：明細を確認してください'):['明細を追加してください'];if(errors.length)throw Error(errors.join(' / '));}if(step>=3){const errors=validateRequest(r);if(errors.length)throw Error(errors.join(' / '));}substep=Math.min(3,Math.max(0,step));r.step=substep;await commit('依頼工程を保存');render();}
function showResponseForm(v){const r=req(),q=r.responses[v]||{version:0,validUntil:r.conditions.needDate,freight:{amount:0,confirmed:false,splitConfirmed:false,type:'fixed',threshold:0},discount:0,discountSplitConfirmed:false,lines:{}};modal('SUPPLIER RESPONSE / 第'+(q.version+1)+'版',`<h2>${esc(vendor(v))}の回答を確認</h2>${(w.documents||[]).some(d=>d.id===q.sourceId)?button('preview-source','回答原本を開く','text',`data-id="${q.sourceId}"`):'<p class="hint">原本：'+esc(q.sourceId||'未登録・手入力')+'</p>'}<form id="responseForm" data-vendor="${v}"><div class="table-wrap"><table><thead><tr><th>明細</th><th>単価</th><th>数量</th><th>単位</th><th>納期(日)</th><th>回答 / 仕様</th></tr></thead><tbody>${r.items.map(i=>{const l=q.lines[i.id];return `<tr data-response-line="${i.id}"><td>${esc(i.name)}<small>${esc(i.model)}</small></td><td><input name="unit" type="number" min="0" step="0.01" value="${l?.unit??''}" style="width:110px"></td><td><input name="qty" type="number" min="0.001" step="0.001" value="${l?.qty??i.qty}" style="width:75px"></td><td><input name="unitLabel" value="${esc(l?.unitLabel||i.unit)}" style="width:60px"></td><td><input name="leadDays" type="number" min="0" value="${l?.leadDays??7}" style="width:60px"></td><td><label class="check"><input name="confirmed" type="checkbox" ${l?.confirmed?'checked':''}>確認済</label><label class="check"><input name="specMatch" type="checkbox" ${l?.specMatch?'checked':''}>仕様一致</label></td></tr>`}).join('')}</tbody></table></div><div class="field-grid"><label>見積有効期限<input name="validUntil" type="date" required value="${esc(q.validUntil)}"></label><label>送料（税抜円）<input name="freight" type="number" required min="0" step="0.01" value="${q.freight.amount}"></label><label>送料方式<select name="feeType"><option value="fixed">固定送料</option><option value="threshold" ${q.freight.type==='threshold'?'selected':''}>一定金額以上で免除</option></select></label><label>免除の基準商品金額<input name="threshold" type="number" min="0" value="${q.freight.threshold||0}"></label><label>値引き（仕入先単位）<input name="discount" type="number" min="0" step="0.01" value="${q.discount}"></label><label class="check"><input name="freightConfirmed" type="checkbox" ${q.freight.confirmed?'checked':''}>送料確認済み</label><label class="check"><input name="splitConfirmed" type="checkbox" ${q.freight.splitConfirmed?'checked':''}>分割購入にも送料条件を適用可</label><label class="check"><input name="discountSplit" type="checkbox" ${q.discountSplitConfirmed?'checked':''}>値引きは分割購入にも適用可</label></div><p class="hint">単価が空欄の行は未回答。確認済みと仕様一致は、原本と照合してからチェックしてください。旧回答版は保持します。</p><div class="modal-actions"><button class="primary">回答を保存して再比較</button></div></form>`)}
async function askData(text){text=String(text||'').trim();if(!text)return;const r=req(),i=currentItem();if(!i)throw Error('品目を選んでください');const history=historyFor(w,i);let answer,evidence=[];if(/送料|配送|分納/.test(text)){const v=r.selected[i.id],q=r.responses[v];answer=q?`${vendor(v)}：送料 ${yen(q.freight.amount)}。送料${q.freight.confirmed?'確認済み':'未確認'}、分割購入${q.freight.splitConfirmed?'適用可':'条件未確認'}です。免除は数量・金額条件が確認できる場合だけ適用します。`:'今回の回答がありません。';evidence=[q?.sourceId||'今回の回答条件'];}else if(/まとめ|交渉|次|数量/.test(text)){const a=recommendations(w,r,i.id,today()).find(x=>x.rule==='R02');answer=a?`${a.body}\n今回分の交渉余地：${yen(a.effect)}（未成立）。元の採用総額は変更しません。`: '同型番・仕様の次案件、近い数量の価格履歴が不足しています。「次案件の使用予定」や確認済み履歴を追加してください。';evidence=a?.evidence||[];}else if(/過去|以前|いくら|単価|掛け率/.test(text)){answer=history.length?`${i.name}の確認済み履歴です。\n`+history.map(h=>`${h.date}：${num(h.qty)}${i.unit}、${yen(h.unit)}/${i.unit}、${vendor(h.vendorId)}。${h.list>0?'掛け率'+(h.unit/h.list*100).toFixed(1)+'%。':''}`).join('\n'):'同じ型番・仕様・単位の確認済み履歴がありません。';evidence=history.map(h=>h.source);}else answer='この質問を判断できる確認済みデータが不足しています。過去単価・数量条件・送料について質問するか、根拠資料を追加してください。';r.chat??=[];r.chat.push({role:'user',text},{role:'assistant',text:answer,evidence});r.chat=r.chat.slice(-20);await commit('取引データへの質問を保存');render();}
function showSuggestion(id){const r=req(),a=recommendations(w,r,currentItem()?.id,today()).find(a=>a.id===id);if(!a)throw Error('根拠が更新されました。提案を再評価してください');const existing=r.proposalResults[id];modal('EVIDENCE & ACTION / '+a.rule,`<h2>${esc(a.title)}</h2><p>${esc(a.body)}</p>${a.effect!==null?`<div class="summary-green">未成立の交渉余地 <strong>${yen(a.effect)}</strong></div><p class="hint">（今回単価 − 過去の条件単価）× 今回数量。送料は今回条件のまま、追加数量の金額とは区別します。</p>`:''}<div class="mini-summary"><h3>根拠・条件</h3><p>${a.evidence.map(esc).join('<br>')||'今回の回答条件'}<br>対象回答版：${a.priceVersion||'未回答'} / ${esc(currentItem()?.model)}</p></div><form id="proposalForm" data-id="${id}"><div class="field-grid"><label>検討状態<select name="status">${['未実施','検討中','交渉中','成立','不成立','見送り'].map(s=>`<option ${s===existing?.status?'selected':''}>${s}</option>`).join('')}</select></label><label>成立した単価（成立時必須）<input name="finalUnit" type="number" min="0" step="0.01" value="${existing?.finalUnit??''}"></label><label class="wide">採否理由・成立条件<textarea name="reason" required>${esc(existing?.reason||'')}</textarea></label></div><div class="inline">${button(a.rule==='R01'?'candidate-supplier':'negotiation-draft',a.rule==='R01'?'依頼先の候補を追加':'再見積の依頼文を作成','',`data-id="${id}"`)}<button class="primary">結果を保存</button></div><p class="hint">成立価格はここで採用額へ反映しません。新しい回答版を確認してから採用し直してください。</p></form>`)}
function showPlan(){const i=currentItem();modal('NEXT PROJECT',`<h2>次案件の使用予定を追加</h2><form id="planForm"><div class="field-grid"><label>案件名<input name="project" required maxlength="100"></label><label>対象品目<select name="item">${req().items.map(x=>`<option value="${x.id}" ${x.id===i?.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>数量<input name="qty" type="number" min="0.001" step="0.001" required></label><label>希望納期<input name="needDate" type="date" required></label><label class="check wide"><input name="confirmed" type="checkbox" required>今回のまとめ依頼に使える確定・選択済み需要</label></div><div class="modal-actions"><button class="primary">使用予定を保存</button></div></form>`)}
function showInvoice(){const a=req().adoptions.at(-1);modal('RECEIPT & INVOICE',`<h2>納品・請求の明細を登録</h2><form id="invoiceForm"><div class="field-grid"><label class="wide">対応する発注行<select name="line">${Object.values(a.comparison.groups).flatMap(g=>g.items.map(i=>`<option value="${g.vendorId}:${i.id}">${esc(vendor(g.vendorId)+' / '+i.name+' / 単価 '+yen(i.unitPrice))}</option>`)).join('')}</select></label><label>今回の納入数量<input name="qty" type="number" min="0.001" step="0.001" required></label><label>請求単価（税抜円）<input name="unit" type="number" min="0" step="0.01" required></label><label>今回請求の送料（仕入先単位）<input name="freight" type="number" min="0" step="0.01" value="0" required></label><label>請求値引き（仕入先単位）<input name="discount" type="number" min="0" step="0.01" value="0"></label><label>実納入日<input name="date" type="date" required value="${today()}"></label><label>原本・ページ・行<input name="source" required placeholder="納品書No. / 請求書p.1 行2"></label><label>承認済み変更額（税抜・本体）<input name="approvedAdjustment" type="number" step="0.01" value="0"></label><label>承認済み送料変更額<input name="approvedFreightAdjustment" type="number" step="0.01" value="0"></label><label>承認者・変更理由（変更時必須）<input name="reason"></label><label>遅延理由<input name="delayReason"></label></div><p class="hint">分納は同じ発注行へ追加。送料は仕入先単位の配送費と区別して記録してください。税・端数の説明は変更理由に残します。</p><div class="modal-actions"><button class="primary">記録して差額を照合</button></div></form>`)}
function showHistoryForm(){modal('PURCHASE HISTORY',`<h2>購入履歴を追加</h2><form id="historyForm"><div class="field-grid"><label>対象品目<select name="item">${(req()?.items||[]).map(i=>`<option value="${i.id}">${esc(i.name+' / '+i.model)}</option>`).join('')}</select></label><label>仕入先<select name="vendor">${w.vendors.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select></label><label>購入日<input name="date" type="date" required></label><label>数量<input name="qty" type="number" min="0.001" step="0.001" required></label><label>仕入単価<input name="unit" type="number" min="0" step="0.01" required></label><label>当時の定価（不明は空欄）<input name="list" type="number" min="0" step="0.01"></label><label>当時の適用銅ベース（電線・円/t）<input name="copperBase" type="number" min="0"></label><label class="wide">根拠原本・取引条件<input name="source" required></label><label class="check wide"><input name="confirmed" type="checkbox" required>型番・数量・仕様・当時条件を照合済み</label></div><div class="modal-actions"><button class="primary">履歴を保存</button></div></form>`)}
function showNoticeForm(){modal('PRICE REVISION',`<h2>価格改定の根拠を登録</h2><form id="noticeForm"><div class="field-grid"><label>対象型番<input name="model" required></label><label>価格種別<select name="kind"><option>定価</option><option>仕入価格</option></select></label><label>改定率（%）<input name="rate" type="number" min="-99" max="1000" step="0.01" required></label><label>発表日<input name="announced" type="date" required></label><label>適用日<input name="effective" type="date" required></label><label>適用基準<select name="basis"><option>出荷日</option><option>発注日</option><option>未確認</option></select></label><label class="wide">根拠資料・URL<input name="source" required></label><label class="check wide"><input name="confirmed" type="checkbox">対象品・価格種別・適用基準を確認済み</label></div><div class="modal-actions"><button class="primary">案内を保存</button></div></form>`)}
async function uploadSources(files){for(const file of files){if(file.size>10*1024*1024)throw Error('1資料10MB以下にしてください');if(!/\.(pdf|xlsx|csv|png|jpe?g)$/i.test(file.name))throw Error('PDF・XLSX・CSV・画像に対応しています');const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(x=>x.toString(16).padStart(2,'0')).join('');w.documents??=[];let d=w.documents.find(d=>d.hash===hash);if(!d){d={id:uid(),name:file.name,kind:file.name.split('.').at(-1).toLowerCase(),hash,status:'要確認',createdAt:new Date().toISOString(),companyId:w.companyId};await store.putFile(file,d);w.documents.push(d);}if(!req().sourceIds.includes(d.id))req().sourceIds.push(d.id);await commit('原本取込：'+file.name);if(/\.(xlsx|csv)$/i.test(file.name)){render();await importSource(d.id);return;}}render();toast('原本を保存しました。明細と数量を確認してください。')}
async function importSource(id){const stored=await store.getFile(id);if(!stored)throw Error('原本が見つかりません。再追加してください');try{await readImportFile(stored.file,'request',id)}catch(e){const d=w.documents.find(d=>d.id===id);if(d){d.status='読取失敗';d.error=e.message;await commit('読取失敗を記録');render();}throw e}}
function showImportPicker(kind){modal('TABLE IMPORT',`<h2>${kind==='response'?'回答見積':'購入履歴'}を取り込む</h2><p>Excel（.xlsx）・CSVの列を対応付け、内容を確認して取り込みます。PDF見積は原本を追加し、回答編集で手入力してください。</p><input id="importFile" type="file" accept=".xlsx,.csv" data-kind="${kind}"><div id="importMapping"></div>`)}
const mappingDefs={request:{name:['品名','商品名'],model:['型番','品番'],qty:['数量'],unitLabel:['単位'],spec:['仕様','要求仕様'],manufacturer:['メーカー','メーカー名']},response:{model:['型番','品番'],qty:['数量'],unitLabel:['単位'],unit:['単価','仕入単価'],lineAmount:['金額','明細金額'],leadDays:['納期日数','納期']},history:{date:['購入日','仕入日'],model:['型番','品番'],qty:['数量'],unitLabel:['単位'],unit:['単価','仕入単価'],list:['定価','当時定価'],source:['原本','根拠資料']}};
async function readImportFile(file,kind,sourceId=''){if(!file)throw Error('ファイルを選択してください');const {readTable}=await import('./imports.bundle.js');let source=sourceId;if(!source){const id=uid(),hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(x=>x.toString(16).padStart(2,'0')).join(''),d={id,name:file.name,kind:file.name.split('.').at(-1),hash,status:'要確認',createdAt:new Date().toISOString(),companyId:w.companyId};await store.putFile(file,d);w.documents??=[];w.documents.push(d);source=id;await commit('表形式の原本保存');}importTable={...await readTable(file),kind,sourceId:source,name:file.name};if(importTable.rows.length>1000)throw Error('一度の取込は1000行以下に分割してください');modal('COLUMN MAPPING / 実ファイル取込',`<h2>列を対応付けて確認</h2><p>${esc(file.name)} / ${importTable.rows.length}行。読み取った数量・単価は、確認後に保存します。</p><div class="settings-grid">${Object.entries(mappingDefs[kind]).map(([k,names])=>{const n=importTable.headers.findIndex(h=>names.includes(h));return `<label>${esc(names[0])}<select data-map="${k}"><option value="">未指定</option>${importTable.headers.map((h,i)=>`<option value="${i}" ${i===n?'selected':''}>${esc(h||'列'+(i+1))}</option>`).join('')}</select></label>`}).join('')}</div>${kind!=='request'?`<div class="field-grid"><label>仕入先<select id="importVendor">${w.vendors.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select></label>${kind==='response'?`<label>有効期限<input id="importValid" type="date" value="${req().conditions.needDate}"></label>`:''}</div>`:''}<div id="importPreview"></div><label class="check" style="margin-top:18px"><input id="importConfirmed" type="checkbox">原本と対応行・数量・単位を確認した</label><div class="modal-actions">${button('import-commit','確認した内容を取り込む','primary')}</div><p class="hint">対応が曖昧な型番は取込対象にしません。明細確認・仕様確認は次の画面で行います。</p>`);renderImportPreview();}
function importCandidates(){const map=Object.fromEntries($$('[data-map]').map(el=>[el.dataset.map,el.value]));return importTable.rows.map((row,index)=>{const value=k=>map[k]!==''&&map[k]!==undefined?String(row[Number(map[k])]??'').trim():'';const result={row:index+2};Object.keys(mappingDefs[importTable.kind]).forEach(k=>result[k]=value(k));for(const k of ['qty','unit','lineAmount','list','leadDays'])if(k in result)result[k]=result[k]===''?null:Number(result[k].replace(/[,¥￥\s]/g,''));const match=req()?.items.filter(i=>norm(i.model)===norm(result.model));result.target=importTable.targetOverrides?.[result.row]?req()?.items.find(i=>i.id===importTable.targetOverrides[result.row]):match?.length===1?match[0]:null;const errors=[];if(!(result.qty>0))errors.push('正の数量が必要');if(!result.unitLabel?.trim())errors.push('単位が必要');if(importTable.kind==='request'&&!result.name.trim())errors.push('品名が必要');if(importTable.kind!=='request'){if(!result.target)errors.push('型番の対応が未確定');if(result.unit===null||!Number.isFinite(result.unit)||result.unit<0)errors.push('単価が必要');if(importTable.kind==='response'&&result.target&&(result.qty!==result.target.qty||result.unitLabel!==result.target.unit))errors.push('数量・単位が依頼と不一致');if(result.lineAmount!==null&&Number.isFinite(result.lineAmount)&&Math.abs(result.lineAmount-amount(result.unit,result.qty))>=.01)errors.push('単価×数量と明細金額が不一致');if(importTable.kind==='history'&&!/^\d{4}-\d{2}-\d{2}$/.test(result.date))errors.push('購入日をYYYY-MM-DDで指定');}result.errors=errors;return result});}
function renderImportPreview(){const rows=importCandidates();$('#importPreview').innerHTML=`<p class="hint">${rows.length}行中 ${rows.filter(r=>!r.errors.length).length}行が取込可能。エラー行は取り込みません。</p>${table(['原本行','品名・型番','数量','単価 / 状態'],rows.slice(0,100).map(r=>[r.row,esc(r.name||r.model)+(importTable.kind!=='request'?`<select data-import-target="${r.row}" aria-label="${r.row}行の対応明細"><option value="">対応行を選択</option>${req().items.map(i=>`<option value="${i.id}" ${r.target?.id===i.id?'selected':''}>${esc(i.name+' / '+i.model)}</option>`).join('')}</select>`:'' ),num(r.qty)+' '+esc(r.unitLabel),(r.unit===null||r.unit===undefined?'':yen(r.unit))+'<small>'+esc(r.errors.join(' / ')||'対応可能')+'</small>']))}`;}
async function commitImport(){if(!$('#importConfirmed').checked)throw Error('原本との照合をチェックしてください');const rows=importCandidates().filter(r=>!r.errors.length);if(!rows.length)throw Error('取込可能な行がありません');const r=req(),kind=importTable.kind;let count=0;if(kind==='request'){if(rows.length+r.items.length>100)throw Error('1依頼100明細までです');for(const x of rows){if(r.items.some(i=>i.sourceId===importTable.sourceId&&i.sourceRow===x.row))continue;r.items.push({id:uid(),name:x.name,manufacturer:x.manufacturer,model:x.model,originalModel:x.model,normalizedModel:norm(x.model),qty:x.qty,unit:x.unitLabel,spec:x.spec,list:0,confirmed:false,sourceId:importTable.sourceId,sourceRow:x.row,reference:importTable.name+' / 先頭シート / '+x.row+'行',updatedAt:new Date().toISOString()});count++;}substep=1;selectedItem=r.items.at(-1)?.id;}else if(kind==='response'){const v=$('#importVendor').value,old=r.responses[v],q={id:uid(),version:(old?.version||0)+1,receivedAt:today(),validUntil:$('#importValid').value,sourceId:importTable.sourceId,freight:old?.freight||{amount:0,confirmed:false,splitConfirmed:false,type:'fixed'},discount:0,discountSplitConfirmed:false,lines:{...old?.lines}};const targets=new Set();for(const x of rows){if(targets.has(x.target.id))throw Error('同じ依頼明細への複数回答は、対応行を分けて確認してください');targets.add(x.target.id);q.lines[x.target.id]={unit:x.unit,qty:x.qty,unitLabel:x.unitLabel,leadDays:x.leadDays??7,available:true,confirmed:false,specMatch:false,sourceRow:x.row,originalModel:x.model};count++;}r.responseVersions??=[];if(old)r.responseVersions.push({vendorId:v,...structuredClone(old)});r.responses[v]=q;stage='compare';}else{const v=$('#importVendor').value;for(const x of rows){if(w.history.some(h=>h.sourceId===importTable.sourceId&&h.sourceRow===x.row))continue;w.history.push({id:uid(),manufacturer:x.target.manufacturer,model:x.target.model,spec:x.target.spec,unitLabel:x.unitLabel,qty:x.qty,unit:x.unit,list:x.list??null,date:x.date,vendorId:v,source:x.source||importTable.name+' / '+x.row+'行',sourceId:importTable.sourceId,sourceRow:x.row,confirmed:true});count++;}stage='history';}const d=w.documents.find(d=>d.id===importTable.sourceId);if(d){d.status='確認済';d.confirmedAt=new Date().toISOString();d.confirmedBy='端末利用者';}invalidate();await commit('表から'+count+'行を取込');closeModal();render();toast(count+'行を取り込みました。未確認の仕様は確認してください。');}
let queue=Promise.resolve();function run(fn){queue=queue.then(async()=>{busy=true;try{await fn()}catch(e){toast(e.message||'操作に失敗しました');console.error(e)}finally{busy=false}});return queue;}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a){e.preventDefault();run(()=>handle(a.dataset.action,a));return}const item=e.target.closest('[data-item]');if(item){selectedItem=item.dataset.item;render();return}const nav=e.target.closest('[data-nav]');if(nav){stage=nav.dataset.nav;render();return}const step=e.target.closest('[data-stage]');if(step){if(!req()){stage='projects'}else{stage=step.dataset.stage;substep=req().step||0;}render()}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='sourceFiles'||el.id==='cameraFile'){const files=[...el.files];run(()=>uploadSources(files));return}if(el.id==='importFile'){const file=el.files[0],kind=el.dataset.kind;run(()=>readImportFile(file,kind));return}if(el.dataset.importTarget){importTable.targetOverrides??={};importTable.targetOverrides[el.dataset.importTarget]=el.value;renderImportPreview();return}if(el.dataset.map!==undefined){renderImportPreview();return}if(el.id==='previewSource'){run(()=>updatePreview(el.value));return}if(el.id==='requestSelect'){requestId=el.value;stage=req().status==='採用確定'?'adopt':'compare';render();return}if(el.id==='historyItem'){selectedItem=el.value;render();return}if(el.id==='dataMode'){run(async()=>{w=await store.load(el.value);localStorage.setItem('gaina-rfq-mode',w.mode);requestId=w.requests[0]?.id;stage=w.requests.length?'compare':'projects';substep=0;render()});return}if(el.dataset.field||el.dataset.itemField||el.dataset.confirmItem||el.dataset.vendor||el.dataset.adoptCheck!==undefined||el.dataset.setting){const value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;run(async()=>{const r=req();if(el.dataset.field){r.conditions[el.dataset.field]=value;invalidate();}if(el.dataset.itemField){const i=currentItem(),k=el.dataset.itemField;i[k]=value;i.confirmed=false;for(const q of Object.values(r.responses))if(q.lines[i.id]){q.lines[i.id].confirmed=false;q.lines[i.id].specMatch=false;}i.updatedAt=new Date().toISOString();if(k==='model')i.normalizedModel=norm(value);const check=$('[data-confirm-item]');if(check)check.checked=false;invalidate();}if(el.dataset.confirmItem){const i=r.items.find(i=>i.id===el.dataset.confirmItem);i.confirmed=value;i.confirmedAt=new Date().toISOString();i.confirmedBy='端末利用者';}if(el.dataset.vendor){r.vendorIds=value?[...new Set([...r.vendorIds,el.dataset.vendor])]:r.vendorIds.filter(v=>v!==el.dataset.vendor);}if(el.dataset.adoptCheck!==undefined){r.confirmChecks??=[false,false,false];r.confirmChecks[Number(el.dataset.adoptCheck)]=value;}if(el.dataset.setting){if(!Number.isFinite(value)||value<1||value>365||el.dataset.setting==='maxSuggestions'&&value>3)throw Error('設定値の範囲を確認してください');w.settings[el.dataset.setting]=value;}await commit();});}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,f=new FormData(form);run(async()=>{const r=req();switch(form.id){case 'newForm':{const old=w.projects.find(p=>p.id===f.get('existing')),name=String(old?.name||f.get('name')).trim();if(!name)throw Error('現場名を入力してください');const n=newRequest(w,name);if(old){w.projects.pop();n.projectId=old.id;n.conditions.destination=old.destination;}requestId=n.id;stage='request';substep=0;await commit('依頼新規作成');closeModal();render();break}case 'vendorForm':{const v=w.vendors.find(v=>v.id===form.dataset.id);if(v){v.name=String(f.get('name')).trim();v.contact=f.get('contact');}else{if(w.vendors.length>=20)throw Error('仕入先は20社まで');const n={id:uid(),name:String(f.get('name')).trim(),contact:f.get('contact'),companyId:w.companyId};w.vendors.push(n);r.vendorIds.push(n.id);}await commit('仕入先保存');closeModal();render();break}case 'responseForm':{const v=form.dataset.vendor,old=r.responses[v],q={id:uid(),version:(old?.version||0)+1,receivedAt:today(),validUntil:f.get('validUntil'),sourceId:old?.sourceId||'手入力確認',freight:{amount:Number(f.get('freight')),confirmed:f.has('freightConfirmed'),splitConfirmed:f.has('splitConfirmed'),type:f.get('feeType'),threshold:Number(f.get('threshold'))},discount:Number(f.get('discount')),discountSplitConfirmed:f.has('discountSplit'),lines:{}};for(const row of form.querySelectorAll('[data-response-line]')){const input=k=>row.querySelector(`[name="${k}"]`);if(input('unit').value==='')continue;q.lines[row.dataset.responseLine]={unit:Number(input('unit').value),qty:Number(input('qty').value),unitLabel:input('unitLabel').value,leadDays:Number(input('leadDays').value),confirmed:input('confirmed').checked,specMatch:input('specMatch').checked,available:true};}r.responseVersions??=[];if(old)r.responseVersions.push({vendorId:v,...structuredClone(old)});r.responses[v]=q;invalidate();await commit('回答第'+q.version+'版を保存');closeModal();render();break}case 'planForm':{const i=r.items.find(i=>i.id===f.get('item'));w.usagePlans.push({id:uid(),project:f.get('project'),model:i.model,spec:i.spec,unit:i.unit,qty:Number(f.get('qty')),needDate:f.get('needDate'),confirmed:f.has('confirmed')});await commit('次案件予定登録');closeModal();render();break}case 'proposalForm':{const a=recommendations(w,r,currentItem().id,today()).find(a=>a.id===form.dataset.id),i=currentItem(),status=f.get('status');if(!a)throw Error('提案の根拠を再確認してください');if(status==='成立'&&f.get('finalUnit')==='')throw Error('成立した単価を記録してください');const old=r.proposalResults[a.id];if(old?.status==='成立')throw Error('成立済み結果は上書きできません。新しい回答版で再評価してください');r.proposalResults[a.id]={id:a.id,title:a.title,rule:a.rule,status,reason:f.get('reason'),finalUnit:f.get('finalUnit')===''?null:Number(f.get('finalUnit')),model:i.model,spec:i.spec,qty:i.qty,vendorId:r.selected[i.id],evidence:structuredClone(a.evidence),initialEffect:a.effect,priceVersion:a.priceVersion,source:'提案結果 '+a.id,recordedAt:new Date().toISOString()};await commit('提案の採否・成立条件保存');closeModal();render();break}case 'invoiceForm':{const [v,id]=f.get('line').split(':'),adjust=Number(f.get('approvedAdjustment')),feeAdjust=Number(f.get('approvedFreightAdjustment'));if((adjust!==0||feeAdjust!==0)&&!String(f.get('reason')).trim())throw Error('承認者・変更理由を入力してください');r.invoiceEntries??=[];r.invoiceEntries.push({id:uid(),adoptionId:r.adoptions.at(-1).id,vendorId:v,itemId:id,qty:Number(f.get('qty')),unit:Number(f.get('unit')),freight:Number(f.get('freight')),discount:Number(f.get('discount')),date:f.get('date'),source:f.get('source'),approvedAdjustment:adjust,approvedFreightAdjustment:feeAdjust,reason:f.get('reason'),delayReason:f.get('delayReason')});r.reconciliations=reconcile(r.adoptions.at(-1),r.invoiceEntries,w.settings.differenceYen);r.actualSummary=actualSummary(r.adoptions.at(-1),r.invoiceEntries,w.settings.differenceYen);await commit('納品・請求の照合結果保存');closeModal();render();break}case 'salesForm':{const i=currentItem();i.saleUnit=Number(f.get('saleUnit'));i.saleConfirmed=f.has('confirmed');i.salesSource=f.get('source');i.salesStatus=f.get('salesStatus');await commit('販売単価の対応付け');closeModal();render();break}case 'historyForm':{const i=r?.items.find(i=>i.id===f.get('item'));if(!i)throw Error('先に依頼明細を登録してください');w.history.push({id:uid(),date:f.get('date'),vendorId:f.get('vendor'),model:i.model,manufacturer:i.manufacturer,spec:i.spec,unitLabel:i.unit,qty:Number(f.get('qty')),unit:Number(f.get('unit')),list:f.get('list')===''?null:Number(f.get('list')),source:f.get('source'),copperBase:f.get('copperBase')===''?null:Number(f.get('copperBase')),wireType:i.wireType,size:i.size,cores:i.cores,packing:i.packing,confirmed:true});await commit('確認済み仕入履歴保存');closeModal();render();break}case 'copperForm':{w.copper??=[];w.copper.push({id:uid(),date:f.get('date'),value:Number(f.get('value')),unit:'円/t',source:f.get('source')});w.copper.sort((a,b)=>a.date.localeCompare(b.date));await commit('銅建値の根拠登録');closeModal();render();break}case 'noticeForm':{if(f.get('effective')<f.get('announced'))throw Error('適用日は発表日以降にしてください');if(f.has('confirmed')&&f.get('basis')==='未確認')throw Error('適用基準を確認してください');w.notices.push({id:uid(),model:norm(f.get('model')),kind:f.get('kind'),rate:Number(f.get('rate')),announced:f.get('announced'),effective:f.get('effective'),basis:f.get('basis'),source:f.get('source'),confirmed:f.has('confirmed'),applied:false});await commit('価格改定根拠保存');closeModal();render();break}default:break;}})});
$('#closeModal').onclick=closeModal;$('#modal').addEventListener('close',()=>document.body.classList.remove('print-doc'));window.addEventListener('afterprint',()=>document.body.classList.remove('print-doc'));$('#saveDraft').onclick=()=>run(async()=>{await commit('下書き保存');toast('保存しました')});$('#help').onclick=()=>run(()=>handle('support'));$('#settings').onclick=()=>{stage='settings';render()};document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='chatQuestion'){e.preventDefault();run(()=>askData(e.target.value));}});
document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone'))e.preventDefault()});document.addEventListener('drop',e=>{if(e.target.closest('#dropzone')){e.preventDefault();const files=[...e.dataTransfer.files];run(()=>uploadSources(files));}});
const hash=location.hash.slice(1);if(['request','compare','adopt','projects','history','market','settings'].includes(hash))stage=hash;if(!w.requests.length)stage='projects';render();

function showSales(){const i=currentItem();if(!i)throw Error('品目を選択してください');modal('SALES LINK',`<h2>販売単価を対応付け</h2><p>${esc(i.name)} / 数量 ${i.qty}${esc(i.unit)}。同じ品目・仕様・数量範囲の売価だけを入力してください。</p><form id="salesForm"><div class="field-grid"><label>販売単価（税抜）<input name="saleUnit" type="number" min="0.01" step="0.01" required value="${i.saleUnit??''}"></label><label>販売明細の状態<select name="salesStatus"><option>作成中</option><option>提出済み・変更承認が必要</option><option>契約済み・変更承認が必要</option></select></label><label class="wide">対応する販売明細の根拠<input name="source" required value="${esc(i.salesSource||'')}"></label><label class="check wide"><input name="confirmed" type="checkbox" required>原価と売上の範囲が同じことを確認</label></div><div class="modal-actions"><button class="primary">対応付けを保存</button></div></form>`)}

async function createNegotiationDraft(id){const r=req(),i=currentItem(),a=recommendations(w,r,i.id,today()).find(x=>x.id===id);if(!a)throw Error('提案を再評価してください');const old=r.proposalResults[id];if(old?.status==='成立')throw Error('成立済み結果は保持します。新しい回答で再評価してください');const text=`${vendor(r.selected[i.id])} 御中

${project(r)?.name} / ${i.name}（${i.model}）の再見積をお願いいたします。
今回数量：${i.qty}${i.unit} / 希望納期：${r.conditions.needDate}
${(a.plans||[]).map(p=>`次案件：${p.project} / ${p.qty}${p.unit} / ${p.needDate}`).join('\n')}
確認内容：${a.body}

案件別の数量・納期を維持し、適用単価、送料、分納条件、有効期限を分けてご回答ください。過去価格の適用は未確定です。`;
 r.proposalResults[id]={...old,id,title:a.title,status:old?.status||'検討中',model:i.model,spec:i.spec,qty:i.qty,vendorId:r.selected[i.id],priceVersion:a.priceVersion,initialEffect:a.effect,evidence:structuredClone(a.evidence),draft:text,allocations:[{project:project(r)?.name,qty:i.qty,needDate:r.conditions.needDate},...(a.plans||[]).map(p=>({project:p.project,qty:p.qty,needDate:p.needDate}))],recordedAt:new Date().toISOString()};await commit('再見積の下書き作成 / 未送信');modal('NEGOTIATION DRAFT',`<h2>再見積の依頼文を作成しました</h2><textarea style="width:100%;min-height:300px">${esc(text)}</textarea><p class="hint">検討記録と案件別数量を保存済み。依頼文は下書きであり、価格・送料・採用総額は変更していません。</p><div class="modal-actions">${button('suggestion-detail','検討結果を記録する','primary',`data-id="${id}"`)}</div>`);}

function showCopperForm(){modal('COPPER BASIS',`<h2>国内銅建値を記録</h2><form id="copperForm"><div class="field-grid"><label>基準日<input name="date" type="date" required></label><label>銅ベース（円/t）<input name="value" type="number" min="1" required></label><label class="wide">公式の根拠資料・URL<input name="source" required></label></div><p class="hint">LMEのUSD/tと混在させず、国内建値の円/tを記録してください。</p><div class="modal-actions"><button class="primary">記録を保存</button></div></form>`)}

function projectLedgerRows(projectId){return w.requests.filter(r=>r.projectId===projectId).flatMap(r=>{const a=r.adoptions.at(-1);if(!a)return[];return Object.values(a.comparison.groups).flatMap(g=>g.items.map((i,index)=>[project(r)?.name,r.number,a.version,vendor(g.vendorId),i.name,i.model,i.qty,i.unit,i.unitPrice,i.lineAmount,index===0?g.freight:'',index===0?g.discount:'',index===0?g.total:'']))});}
function showProjectLedger(id){const requests=w.requests.filter(r=>r.projectId===id&&r.adoptions.length),total=requests.reduce((n,r)=>n+r.adoptions.at(-1).plannedCost,0),rows=projectLedgerRows(id);modal('PROJECT LEDGER',`<h2>${esc(w.projects.find(p=>p.id===id)?.name)}の採用明細</h2><p>${requests.length}件の依頼 / 最新の確定版のみ集計。予定原価合計 ${yen(total)}</p>${table(['依頼 / 版','品名・型番','仕入先','数量','本体金額'],rows.map(r=>[esc(r[1])+' / '+r[2],esc(r[4])+'<small>'+esc(r[5])+'</small>',esc(r[3]),num(r[6])+esc(r[7]),yen(r[9])]))}<div class="modal-actions">${button('project-export','この現場のExcelを出力','primary',`data-id="${id}"`)}</div><p class="hint">送料・値引きは依頼ごとの配送条件で保持。過去の採用版や未成立の提案は重複集計しません。</p>`);}
